import {solutions} from '../../data/content';import {ButtonLink} from '../../components/Site';
export const metadata={title:'Soluciones industriales'};
export default function Soluciones(){return <section className="section compact"><span className="eyebrow">CAPACIDADES Y OPORTUNIDADES</span><h1>Aplicaciones para explorar.</h1><p className="lead">Un catálogo de ideas para iniciar conversaciones técnicas. Estas aplicaciones son conceptuales; no implican fabricación, disponibilidad ni asociaciones comerciales confirmadas.</p>{solutions.map((s,i)=><section className="solution-group" key={s.category}><span className="eyebrow">0{i+1} / CONCEPTUAL · SUJETO A FACTIBILIDAD</span><h2>{s.category}</h2><div className="solution-grid">{s.items.map(item=><div className="solution-item" key={item}><h3>{item}</h3><p>Aplicación potencial. Definir cargas, entorno, dimensiones, normas y ensayos antes de cotizar.</p></div>)}</div></section>)}<div className="actions"><ButtonLink href="/contacto">Plantear un desarrollo</ButtonLink></div></section>}
